-- One-time, idempotent work schedule requested by Michelle on October 14, 2026.
-- Existing task dates, statuses, notes text, evidence and town records are preserved.
begin;
do $$
declare original_ids uuid[]; original_state text; after_state text; town_state text; town_after text;
begin
 perform pg_advisory_xact_lock(hashtext('cc-phase-one-projects-20261015'));
 select array_agg(id),md5(string_agg(jsonb_build_array(id,status,completed_at,completed_by,completed_by_name)::text,'' order by id)) into original_ids,original_state from public.cc_tasks where workspace_id='c8748032-cdd3-443b-8c56-2e846cc9bf31';
 select md5(string_agg(to_jsonb(t)::text,'' order by id)) into town_state from public.cc_tasks t where workspace_id='c8748032-cdd3-443b-8c56-2e846cc9bf31' and (notes::jsonb ? 'townKey' or notes::jsonb->>'recordType'='town');
 -- Put website/operations tasks under their own brand, without touching client profiles.
 update public.cc_tasks t set notes=(t.notes::jsonb||jsonb_build_object('projectKey','operations:'||b.name,'phase','directory-businesses-20261015','ownerAction',t.title in ('Complete Square identity verification','Link the business bank account in Square'),'projectOrder',case when t.title ilike '%square%' then 1 when t.title ilike '%pricing%' or t.title ilike '%intake%' or t.title ilike '%claim-a-business%' then 10 when t.title ilike '%agreement%' or t.title ilike '%onboarding%' or t.title ilike '%proposal%' then 20 else 100 end))::text,details=t.details||jsonb_build_object('project',b.name||' website & operations')
 from public.cc_businesses b where t.business_id=b.id and t.workspace_id=b.workspace_id and t.workspace_id='c8748032-cdd3-443b-8c56-2e846cc9bf31' and b.name in ('MKT Visibility','Loving Longmont','MKT Colorado') and b.kind='Partner-owned Business' and not(t.notes::jsonb ? 'townKey') and coalesce(t.notes::jsonb->>'recordType','')<>'town' and not(t.notes::jsonb ? 'businessChecklistKey') and t.type<>'Follow-up' and coalesce(t.notes::jsonb->>'contactChannel','Task') not in ('Email','Phone call') and not(t.notes::jsonb ? 'phase');
 -- Assign the three unlinked operations tasks using their already saved brand.
 update public.cc_tasks t set notes=(t.notes::jsonb||jsonb_build_object('projectKey','operations:'||(t.notes::jsonb->>'brand'),'phase','directory-businesses-20261015'))::text where workspace_id='c8748032-cdd3-443b-8c56-2e846cc9bf31' and business_id is null and notes::jsonb->>'brand' in ('MKT Visibility','Loving Longmont','MKT Colorado') and not(notes::jsonb ? 'townKey') and not(notes::jsonb ? 'townName') and not(notes::jsonb ? 'recordType') and not(notes::jsonb ? 'phase');
 -- This aggregate town assignment is reserved for the later town session, too.
 update public.cc_tasks set notes=(notes::jsonb||jsonb_build_object('deferredTownWork',true))::text where workspace_id='c8748032-cdd3-443b-8c56-2e846cc9bf31' and title='Complete one town page and its merchandise links' and not(notes::jsonb ? 'deferredTownWork');
 -- Fill only missing payment-readiness checks. A canceled payment-link task stays canceled.
 insert into public.cc_tasks(workspace_id,business_id,title,type,status,priority,assignee,notes,details)
 select b.workspace_id,b.id,v.title,'Task','Open','High','Michelle',jsonb_build_object('format','mkt-portfolio-v1','brand',b.name,'area','Website','operationsTask',true,'projectKey','operations:'||b.name,'projectOrder',v.ord,'ownerAction',v.owner_action,'phaseSeed','directory-businesses-20261015','text',v.description)::text,jsonb_build_object('project',b.name||' website & operations','suggestion_key',v.seed)
 from (values
 ('Loving Longmont','Verify available annual listing checkout links','Confirm which secure Square links already exist and match the approved current listing packages, offer availability, duration and renewal terms. Preserve the canceled older task; record verified links here.','phase1:ll:checkout',11,false),
 ('Loving Longmont','Test listing intake, checkout and confirmation on phone and desktop','Verify the full path from pricing to business intake to secure payment and confirmation. Michelle completes any account verification or payment test requiring her account. Record results; no purchase is authorized by scheduling this task.','phase1:ll:test',15,true),
 ('Loving Longmont','Document paid-listing fulfillment and renewal tracking','Record where orders arrive, how payment is verified, who publishes the purchased listing, how the client receives its link, and how the end date and renewal reminder are tracked. Include the matching MKT Colorado listing when included by the approved package.','phase1:ll:fulfillment',18,false),
 ('MKT Colorado','Create or verify secure checkout links for business listing purchases','Check the current approved claim/update and annual listing offers and prices before creating or reusing Square links. Record what a customer buys, the service term and renewal terms. Product-store payments are separate.','phase1:co:checkout',11,true),
 ('MKT Colorado','Connect business purchase intake and checkout to the website','Connect the approved listing purchase links and intake form to the relevant claim/pricing actions. Capture the business identity and purchased package so an order can be matched to the correct profile.','phase1:co:connect',12,false),
 ('MKT Colorado','Test listing purchase confirmation and fulfillment','Verify phone and desktop purchase paths, confirmation, owner notifications, business-profile matching, listing publication steps and renewal tracking. Record test evidence; do not charge a card merely to mark this task complete.','phase1:co:test',15,true),
 ('MKT Visibility','Verify the service proposal-to-payment workflow','Use the existing pricing, proposal, agreement and onboarding tasks. Verify a customer can approve a clear scope, receive the correct invoice or checkout link, and receive confirmation and next steps. No client contact or charge is authorized by this scheduled work session.','phase1:mkt:revenue',25,false)
 ) v(brand,title,description,seed,ord,owner_action) join public.cc_businesses b on b.name=v.brand and b.kind='Partner-owned Business'
 where b.workspace_id='c8748032-cdd3-443b-8c56-2e846cc9bf31' and not exists(select 1 from public.cc_tasks t where t.workspace_id=b.workspace_id and t.business_id=b.id and t.details->>'suggestion_key'=v.seed);
 -- Operations get the first three workdays. These are work sessions, not deadlines.
 insert into public.cc_tasks(workspace_id,title,type,status,priority,due_date,assignee,notes)
 select 'c8748032-cdd3-443b-8c56-2e846cc9bf31',v.brand,'Project','Open','High',v.work_date::date,'Michelle',jsonb_build_object('format','mkt-portfolio-v1','recordType','workProject','projectKey','operations:'||v.brand,'brand',v.brand,'focus',v.focus,'phaseSeed','directory-businesses-20261015','text','Scheduled project work session. Checklists retain their original task deadlines and completion history.')::text
 from (values('MKT Visibility','2026-10-15','Square readiness, service pricing & onboarding'),('Loving Longmont','2026-10-16','Listing payments, intake & confirmation'),('MKT Colorado','2026-10-19','Business listing purchases & fulfillment')) v(brand,work_date,focus)
 where not exists(select 1 from public.cc_tasks t where t.workspace_id='c8748032-cdd3-443b-8c56-2e846cc9bf31' and t.notes::jsonb->>'recordType'='workProject' and t.notes::jsonb->>'projectKey'='operations:'||v.brand);
 -- Deduplicate businesses listed on both directories. Schedule the first 20 weekdays;
 -- remaining businesses stay in the alphabetical project queue for the next planning pass.
 with eligible as(
 select b.*,row_number() over(order by lower(b.name),b.id) n from public.cc_businesses b where b.workspace_id='c8748032-cdd3-443b-8c56-2e846cc9bf31' and b.kind<>'Partner-owned Business' and b.status='Active' and coalesce((case when b.notes is json object then b.notes::jsonb else '{}'::jsonb end)->>'outreachDecision','')<>'Not a match' and exists(select 1 from public.cc_listings l where l.business_id=b.id and l.site in ('Loving Longmont','MKT Colorado') and l.status<>'Archived')
 ), workdays as(select d::date work_date,row_number() over(order by d) n from generate_series(date '2026-10-15',date '2026-11-30',interval '1 day') d where extract(isodow from d)<6)
 insert into public.cc_tasks(workspace_id,title,type,status,priority,due_date,assignee,notes)
 select b.workspace_id,b.name,'Project','Open','Normal',d.work_date,'Michelle',jsonb_build_object('format','mkt-portfolio-v1','recordType','workProject','projectKey','business:'||b.id,'projectBusinessId',b.id,'brand',case when exists(select 1 from public.cc_listings l where l.business_id=b.id and l.site='Loving Longmont' and l.status<>'Archived') then 'Loving Longmont' else 'MKT Colorado' end,'phaseSeed','directory-businesses-20261015','focus','Business page completion checklist','text','Alphabetical business-page work session. This is not a client appointment or a completion deadline; reschedule if more work is needed. Town pages are outside this phase.')::text
 from eligible b join workdays d using(n) where b.n<=20 and not exists(select 1 from public.cc_tasks t where t.workspace_id=b.workspace_id and t.notes::jsonb->>'recordType'='workProject' and t.notes::jsonb->>'projectKey'='business:'||b.id);
 select md5(string_agg(jsonb_build_array(id,status,completed_at,completed_by,completed_by_name)::text,'' order by id)) into after_state from public.cc_tasks where id=any(original_ids);
 if original_state is distinct from after_state then raise exception 'Existing task status or completion provenance changed'; end if;
 select md5(string_agg(to_jsonb(t)::text,'' order by id)) into town_after from public.cc_tasks t where workspace_id='c8748032-cdd3-443b-8c56-2e846cc9bf31' and (notes::jsonb ? 'townKey' or notes::jsonb->>'recordType'='town');
 if town_state is distinct from town_after then raise exception 'Town records changed'; end if;
end $$;
commit;
select title,due_date,notes::jsonb->>'focus' focus from public.cc_tasks where workspace_id='c8748032-cdd3-443b-8c56-2e846cc9bf31' and notes::jsonb->>'recordType'='workProject' order by due_date,title;
